/**
 * AI provider connectors: org-owned reference identities, model_name-keyed
 * lookups. Never their own top-level catalog bag — nested under their
 * owning provider instead (`catalog.aiProviders.<provider>.models.<model>`,
 * rendered specially in `src/catalog/org.ts`), since a connector's
 * `provider_id` is a real reference to one of the 10 `elementum_<type>_
 * ai_provider` blocks (entities/org/ai-provider.ts), not a plain string.
 */
import { NO_CATALOG, NO_LIFECYCLE } from "../../graph/types.js";
/** org.ts / OrgRefLookup bag — keep in lockstep with `data.orgBag`. */
export const CONNECTOR_ORG_BAG = "connectors";
export const connectorModule = {
    kind: "connector",
    stream: { role: "orgExport" },
    data: {
        participates: true,
        lookupAttr: "model_name",
        providerRefAttr: "provider_id",
        catalogKind: "connector",
        orgBag: CONNECTOR_ORG_BAG,
        // Agents pin connectors (`ai_provider_connector_id`), so build emits this
        // data source and the build-vs-export scopes it (M3).
        referencedByBuild: true,
    },
    authoring: { unit: "none" },
    parents: [{ parent: "org", child: "connector" }],
    resource: {
        shape: "single",
        resourceType: "elementum_ai_provider_connector",
        adoptable: false,
    },
    lifecycle: NO_LIFECYCLE,
    canvas: { participates: true, label: "AI Provider Connectors", glyph: "⚡", component: "orgIdentity" },
    catalog: NO_CATALOG,
};
